<?php
function icon(string $name,string $class=''): string {
    $paths=['home'=>'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z','palette'=>'M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-4 2 2 0 0 1 1-3h3a3 3 0 0 0 3-3c0-5-4-8-9-8z M7 10h.01M10 6h.01M16 7h.01M6 15h.01','gavel'=>'m14 3 7 7-3 3-7-7zM5 12l7 7-3 3-7-7zM12 12l-5 5M17 17l5 5','camera'=>'M3 7h4l2-3h6l2 3h4v13H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0','pen'=>'m16 3 5 5-12 12-6 1 1-6zM14 5l5 5M4 15l5 5','brush'=>'m14 3 7 7-9 9-7-7zM5 12c-5 2 1 6-4 9 7 1 10-2 8-5','gallery'=>'M3 5h18v16H3zM7 1v4M17 1v4M3 15l5-5 5 5 3-3 5 5','feed'=>'M4 4h16v16H4zM8 8h8M8 12h8M8 16h5','heart'=>'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8','bag'=>'M5 7h14l2 14H3zM8 8V6a4 4 0 0 1 8 0v2','search'=>'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0','arrow'=>'M4 12h16M14 6l6 6-6 6','user'=>'M20 21a8 8 0 0 0-16 0M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','bell'=>'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4','check'=>'m5 12 4 4L19 6','plus'=>'M12 4v16M4 12h16','clock'=>'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0','menu'=>'M4 6h16M4 12h16M4 18h16','share'=>'m14 3 7 6-7 6V11C6 11 3 15 3 20 1 10 5 7 14 7z','bookmark'=>'M6 3h12v18l-6-4-6 4z','logout'=>'M9 3H3v18h6M9 12h12M16 7l5 5-5 5','settings'=>'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M9 15v6','spark'=>'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z'];
    return '<svg class="icon '.e($class).'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'.($paths[$name]??$paths['gallery']).'"/></svg>';
}
function url(string $p,array $args=[]):string{return '/?'.http_build_query(['p'=>$p]+$args);}
function form(string $action,array $fields=[],string $class=''):void{
    echo '<form method="post" action="/" class="'.e($class).'">'.token_field().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="return" value="'.e($_SERVER['REQUEST_URI']??'/?p=home').'">';
    foreach($fields as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';
}
function action_button(string $action,array $fields,string $label,string $class='btn btn-small'):void{form($action,$fields,'inline-form');echo '<button class="'.e($class).'">'.$label.'</button></form>';}
function visual_media(?array $m,string $class=''):void {
    if(!$m){echo '<div class="art-visual empty-art '.e($class).'" role="img" aria-label="Artwork image unavailable">'.icon('gallery').'</div>';return;}
    $path=$m['storage_path'];$src='/image.php?id='.(int)$m['id'];
    if(preg_match('/#tile(\d)/',$path,$match))echo '<div class="art-visual art-atlas tile-'.(int)$match[1].' '.e($class).'" style="background-image:url('.e($src).')" role="img" aria-label="'.e($m['alt_text']).'"></div>';
    elseif(preg_match('/#tool(\d)/',$path,$match))echo '<div class="art-visual tool-atlas tool-'.(int)$match[1].' '.e($class).'" style="background-image:url('.e($src).')" role="img" aria-label="'.e($m['alt_text']).'"></div>';
    else echo '<img class="art-visual '.e($class).'" src="'.e($src).'" alt="'.e($m['alt_text']).'" loading="lazy">';
}
function listing_media(array $l):?array{return $l['artwork_id']?one('SELECT m.* FROM media m JOIN artwork_images i ON i.media_id=m.id WHERE i.artwork_id=? ORDER BY i.sort_order LIMIT 1',[$l['artwork_id']]):one('SELECT m.* FROM media m JOIN listing_images i ON i.media_id=m.id WHERE i.listing_id=? ORDER BY i.sort_order LIMIT 1',[$l['id']]);}
function avatar(string $name,string $class=''):string{$parts=explode(' ',$name);return '<span class="avatar '.e($class).'">'.e(mb_substr($parts[0],0,1).mb_substr($parts[count($parts)-1],0,1)).'</span>';}
function badge(string $value):string{return '<span class="badge '.e($value).'">'.($value==='dalubhasa'?icon('check'):'✦').' '.e(ucfirst($value)).'</span>';}
function status(string $value):string{return '<span class="status status-'.e($value).'">'.e(ucwords(str_replace('_',' ',$value))).'</span>';}
function page_heading(string $eyebrow,string $title,string $lead=''):void{echo '<div class="page-heading"><div><span class="eyebrow">'.e($eyebrow).'</span><h1>'.e($title).'</h1>';if($lead)echo '<p>'.e($lead).'</p>';echo '</div></div>';}
function empty_state(string $title,string $text,string $link='catalog'):void{echo '<div class="empty-state">'.icon('gallery').'<h2>'.e($title).'</h2><p>'.e($text).'</p><a class="btn btn-outline" href="'.url($link).'">Explore SIKHAYA '.icon('arrow').'</a></div>';}
function card(array $l):void{
    $u=user();$saved=$u&&one('SELECT id FROM saved_items WHERE user_id=? AND listing_id=?',[$u['id'],$l['id']]);
    echo '<article class="art-card card"><div class="card-picture"><a class="m-zoom" href="'.url('detail',['id'=>$l['id']]).'" aria-label="View '.e($l['title']).'">';visual_media(listing_media($l));echo '</a>';
    form('save',['id'=>$l['id'],'type'=>'listing'],'save-form');echo '<button class="save-button '.($saved?'is-saved':'').'" aria-label="'.($saved?'Unsave ':'Save ').e($l['title']).'">'.icon('heart').'</button></form>';
    if($l['section']==='subasta'){$a=one('SELECT * FROM auctions WHERE listing_id=?',[$l['id']]);echo '<span class="image-label">'.icon('clock').' <span data-end="'.e($a['ends_at']).'">'.($a['status']==='ended'?'Ended':'Auction').'</span></span>';}
    if($l['stock_qty']===0)echo '<span class="image-label">Sold out</span>';
    echo '</div><div class="card-content"><p class="card-meta">'.e($l['category']).'</p><h3><a href="'.url('detail',['id'=>$l['id']]).'">'.e($l['title']).'</a></h3><a class="artist-link" href="'.url('artist',['id'=>$l['seller_id']]).'">'.e($l['display_name']??one('SELECT display_name FROM users WHERE id=?',[$l['seller_id']])['display_name']).'</a><div class="card-bottom"><strong>'.money((int)$l['unit_price_centavos']).'</strong><span>'.($l['section']==='arkilikha'?'/ day':($l['section']==='gawang_hiling'?'starting at':($l['section']==='subasta'?'opening bid':'Original & local'))).'</span></div></div></article>';
}
