    <a class="skip-link" href="#main">Skip to content</a><aside class="sidebar" id="sidebar"><a class="brand" href="/"><img src="/assets/images/sikhaya-logo.png" alt="SIKHAYA — fire, air, and a paintbrush"><span>A home for Filipino creativity</span></a><nav aria-label="Main navigation"><a class="nav-item <?=$page==='home'?'active':''?>" href="/"><?=icon('home')?> <span>Discover</span></a><span class="nav-caption">EXPLORE SIKHAYA</span><?php foreach(SECTIONS as $s=>$v):$target=$s==='museo'?'artists':'catalog';?><a class="nav-item <?=($page==='catalog'&&($_GET['section']??'')===$s)||($page==='artists'&&$s==='museo')?'active':''?>" href="<?=url($target,$target==='catalog'?['section'=>$s]:[])?>"><?=icon($v[2])?><span><?=$v[0]?><small><?=$v[1]?></small></span></a><?php endforeach;?><span class="nav-rule"></span><a class="nav-item <?=$page==='feed'?'active':''?>" href="<?=url('feed')?>"><?=icon('feed')?> <span>Community feed</span></a><a class="nav-item <?=$page==='saved'?'active':''?>" href="<?=url('saved')?>"><?=icon('bookmark')?> <span>Saved collection</span></a><?php if($u):?><a class="nav-item <?=$page==='orders'?'active':''?>" href="<?=url('orders')?>"><?=icon('bag')?> <span>My orders</span></a><a class="nav-item <?=$page==='work'?'active':''?>" href="<?=url('work')?>"><?=icon('clock')?> <span>Rentals & commissions</span></a><?php if($u['role']==='artist'):?><a class="nav-item <?=$page==='studio'?'active':''?>" href="<?=url('studio')?>"><?=icon('pen')?> <span>My studio</span></a><?php endif;if($u['role']==='admin'):?><a class="nav-item <?=$page==='admin'?'active':''?>" href="<?=url('admin')?>"><?=icon('settings')?> <span>Admin workspace</span></a><?php endif;endif;?></nav><div class="sidebar-bottom"><span class="little-star">✦</span><p>A little support.<br>A world of possibility.</p><a href="<?=url('about')?>">The story of SIKHAYA <?=icon('arrow')?></a><span class="demo-mark">THE ENTREPRENEURIAL MIND · SCHOOL DEMO</span></div></aside>
    <div class="app-main"><header class="topbar"><button class="icon-button menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="sidebar"><?=icon('menu')?></button><form class="search-box" action="/" method="get"><input type="hidden" name="p" value="catalog"><?=icon('search')?><input aria-label="Search art, materials, and artists" name="q" placeholder="Find a piece that feels like you" value="<?=e($_GET['q']??'')?>"><button aria-label="Search" class="search-submit"><?=icon('arrow')?></button></form><div class="top-actions"><a class="about-link" href="<?=url('about')?>">Our story</a><a class="icon-button cart-link" href="<?=url('cart')?>" aria-label="Shopping bag, <?=$count?> items"><?=icon('bag')?><?php if($count):?><b><?=$count?></b><?php endif;?></a><?php if($u):?><a class="icon-button" href="<?=url('activity')?>" aria-label="Notifications, <?=$notices?> unread"><?=icon('bell')?><?php if($notices):?><i class="notice-dot"></i><?php endif;?></a><a class="user-link" href="<?=url('profile')?>"><?=avatar($u['display_name'])?><span><?=e(explode(' ',$u['display_name'])[0])?></span></a><?php else:?><a class="btn btn-small" href="<?=url('login')?>">Sign in <?=icon('arrow')?></a><?php endif;?></div></header>
    <main id="main" tabindex="-1"><?php if(isset($_SESSION['flash'])):[$kind,$msg]=$_SESSION['flash'];unset($_SESSION['flash']);?><div class="flash <?=$kind?>" role="status"><?=icon($kind==='success'?'check':'bell')?><?=e($msg)?><button type="button" aria-label="Dismiss message" data-dismiss>×</button></div><?php endif;
}
function shell_end():void{?><footer class="footer"><a class="wordmark" href="/">sikhaya<span>✦</span></a><p>Alisin ang tanikala, lumikha nang malaya.</p><div><a href="<?=url('about')?>">About</a><a href="<?=url('help')?>">How it works</a><a href="<?=url('login')?>">Demo accounts</a></div><small>School prototype · Fictional listings · No real payments · Sample art generated for this demo; licensed photos credited in ASSET_CREDITS.md</small></footer></main></div></body></html><?php }
function home():void{
    $featured=all("SELECT l.*,u.display_name FROM listings l JOIN users u ON u.id=l.seller_id WHERE l.section='likha_lokal' AND l.status='published' ORDER BY l.id LIMIT 4");
    ?><section class="hero" data-enter><div class="hero-copy"><div class="eyebrow"><span class="tiny-line"></span> MADE HERE. MEANT TO BE FOUND.</div><h1>For the art.<br>For the <em>artist.</em></h1><p>Discover a piece of the Philippines.<br>Original art, local hands, and stories worth bringing home.</p><div class="hero-actions"><a class="btn" href="<?=url('catalog')?>">Browse artworks <?=icon('arrow')?></a><a class="text-link" href="<?=url('artists')?>">Meet the artists <?=icon('arrow')?></a></div><div class="hero-foot"><div class="avatar-stack"><?=avatar('Amara Reyes')?><?=avatar('Lian Cruz')?><?=avatar('Isabel Flores')?></div><p>A space for local talent.<br><strong>A little more room to create.</strong></p></div></div><div class="hero-art" data-enter-media><span class="hero-stamp">LIKHA LOKAL<br><b>Made with sikhay.<br>Shared with laya.</b></span><a class="hero-frame" href="<?=url('detail',['id'=>1])?>" aria-label="Explore Where the light stays"><?php visual_media(listing_media($featured[0]));?></a><div class="hero-art-info"><div><strong>Where the light stays</strong><span>Amara Reyes · Oil on canvas</span></div><a class="round-arrow" href="<?=url('detail',['id'=>1])?>" aria-label="View artwork"><?=icon('arrow')?></a></div><span class="art-edition">A SIKHAYA DEMO COLLECTION / 2026</span></div></section>
    <section class="discover-sections"><div class="section-heading"><div><h2>Six ways to create and connect.</h2></div><span class="quiet-label">Art is just the beginning.</span></div><div class="section-links"><?php foreach(SECTIONS as $s=>$v):?><a href="<?=url($s==='museo'?'artists':'catalog',$s==='museo'?[]:['section'=>$s])?>"><span class="section-icon <?=$s?>"><?=icon($v[2])?></span><strong><?=$v[0]?></strong><small><?=$v[1]?></small><?=icon('arrow','section-arrow')?></a><?php endforeach;?></div></section>
    <section class="featured"><div class="section-heading"><div><h2>Made by local hands.</h2></div><a class="text-link" href="<?=url('catalog',['section'=>'likha_lokal'])?>">View all artworks <?=icon('arrow')?></a></div><div class="art-grid"><?php foreach($featured as $l)card($l);?></div></section>
    <section class="community-band"><div><span class="eyebrow">THERE’S A STORY BEHIND EVERY STROKE</span><h2>Art feels better<br>when it’s shared.</h2><p>Step into the studio. Share your work, follow a conversation, and find your next spark in the community.</p><a class="btn" href="<?=url('feed')?>">Explore the community <?=icon('arrow')?></a></div><div class="community-preview"><?php foreach(all("SELECT p.*,u.display_name FROM posts p JOIN users u ON u.id=p.author_id WHERE p.shared_post_id IS NULL ORDER BY p.id LIMIT 2") as $p):?><a class="mini-post" href="<?=url('feed',['post'=>$p['id']])?>"><div><?=avatar($p['display_name'])?><strong><?=e($p['display_name'])?></strong><span>In the studio</span></div><?php visual_media(one('SELECT m.* FROM media m JOIN post_images i ON i.media_id=m.id WHERE i.post_id=? LIMIT 1',[$p['id']]));?></a><?php endforeach;?></div></section>
    <section class="statement" id="freedom"><span class="eyebrow">SIKHAY + LAYA</span><h2 data-moment="word-highlight">Alisin ang tanikala,<br><em>lumikha nang malaya.</em></h2><a class="text-link" href="<?=url('about')?>">The meaning behind SIKHAYA <?=icon('arrow')?></a></section><?php
}
function catalog():void{
    $section=(string)($_GET['section']??'');if($section&&!isset(SECTIONS[$section]))$section='';$q=trim((string)($_GET['q']??''));$cat=trim((string)($_GET['category']??''));$sort=(string)($_GET['sort']??'newest');$page=max(1,(int)($_GET['page']??1));
    page_heading($section?SECTIONS[$section][0]:'THE SIKHAYA COLLECTION',$section?SECTIONS[$section][1]:'Find something that speaks to you.',$section==='subasta'?'Find your next piece. Place a bid and make it yours.':($section==='arkilikha'?'Good tools, ready when inspiration arrives.':($section==='gawang_hiling'?'Your story, brought to life by local hands.':'A collection of local art, objects, and creative possibilities.')));
    echo '<div class="catalog-tabs"><a class="'.(!$section?'selected':'').'" href="'.url('catalog').'">All discoveries</a>';foreach(SECTIONS as $s=>$v)echo '<a class="'.($section===$s?'selected':'').'" href="'.url($s==='museo'?'artists':'catalog',$s==='museo'?[]:['section'=>$s]).'">'.$v[0].'</a>';echo '</div>';
    $where="l.status IN ('published','sold_out') AND u.status='active' AND (l.artwork_id IS NULL OR (w.status='visible'))";$args=[];
    if($section){$where.=' AND l.section=?';$args[]=$section;}if($q){$where.=' AND (l.title LIKE ? OR l.description LIKE ? OR u.display_name LIKE ? OR l.category LIKE ?)';array_push($args,...array_fill(0,4,'%'.$q.'%'));}if($cat){$where.=' AND l.category=?';$args[]=$cat;}
    foreach(['min'=>' >=','max'=>' <='] as $key=>$op)if(isset($_GET[$key])&&$_GET[$key]!==''&&is_numeric($_GET[$key])){$where.=' AND l.unit_price_centavos'.$op.' ?';$args[]=(int)round((float)$_GET[$key]*100);}
    $from=' FROM listings l JOIN users u ON u.id=l.seller_id LEFT JOIN artworks w ON w.id=l.artwork_id WHERE '.$where;
    $count=(int)query('SELECT COUNT(*)'.$from,$args)->fetchColumn();$order=match($sort){'price_low'=>'l.unit_price_centavos ASC','price_high'=>'l.unit_price_centavos DESC','ending'=>'COALESCE((SELECT ends_at FROM auctions WHERE listing_id=l.id),\'9999\') ASC',default=>'l.id ASC'};
    ?><form class="filterbar" method="get"><input type="hidden" name="p" value="catalog"><input type="hidden" name="section" value="<?=e($section)?>"><label class="filter-search"><?=icon('search')?><input name="q" placeholder="Search the collection" aria-label="Search this collection" value="<?=e($q)?>"></label><label><span>Category</span><select name="category"><option value="">All categories</option><?php foreach(all('SELECT DISTINCT category FROM listings'.($section?' WHERE section=?':'').' ORDER BY category',$section?[$section]:[]) as $c):?><option <?=$cat===$c['category']?'selected':''?>><?=e($c['category'])?></option><?php endforeach;?></select></label><label><span>Min ₱</span><input class="price-filter" type="number" min="0" name="min" placeholder="Any" value="<?=e($_GET['min']??'')?>"></label><label><span>Max ₱</span><input class="price-filter" type="number" min="0" name="max" placeholder="Any" value="<?=e($_GET['max']??'')?>"></label><label><span>Sort by</span><select name="sort"><?php foreach(['newest'=>'Curated order','price_low'=>'Price: low to high','price_high'=>'Price: high to low','ending'=>'Ending soon'] as $k=>$v):?><option value="<?=$k?>" <?=$sort===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><button class="btn btn-small">Apply filters</button></form><div class="results-count"><span><strong><?=$count?></strong> discoveries<?=$q?' for “'.e($q).'”':''?></span><span><?=icon('check')?> Local creativity, in good company</span></div><?php
    $rows=all('SELECT l.*,u.display_name'.$from.' ORDER BY '.$order.' LIMIT 12 OFFSET '.(($page-1)*12),$args);
    if(!$rows)empty_state('Nothing here just yet.','Try another search or a wider price range.');else{echo '<div class="art-grid">';foreach($rows as $l)card($l);echo '</div>';}
    if($count>12){echo '<nav class="pagination" aria-label="Results pages">';for($i=1;$i<=ceil($count/12);$i++)echo '<a class="'.($i===$page?'selected':'').'" href="'.e(url('catalog',array_merge($_GET,['page'=>$i]))).'">'.$i.'</a>';echo '</nav>';}
}
function detail():void{
    $l=listing((int)($_GET['id']??0));$u=user();if(in_array($l['status'],['hidden','archived'])||($l['artwork_id']&&$l['artwork_status']!=='visible')){empty_state('This piece is unavailable.','Explore more work from the collection.');return;}
    ?><a class="back-link" href="<?=url('catalog',['section'=>$l['section']])?>">← Back to <?=SECTIONS[$l['section']][0]?></a><div class="detail-grid"><div class="detail-visual"><?php visual_media(listing_media($l));?><p class="image-credit">Sample image for this school prototype. No real item is sold.</p></div><div class="detail-copy"><span class="eyebrow"><?=e(SECTIONS[$l['section']][0])?> / <?=e($l['category'])?></span><h1><?=e($l['title'])?></h1><a class="detail-artist" href="<?=url('artist',['id'=>$l['seller_id']])?>"><?=avatar($l['display_name'])?><span><strong><?=e($l['display_name'])?></strong><small><?=e($l['region'])?></small></span><?=badge($l['badge'])?></a><p class="detail-description"><?=nl2br(e($l['description']))?></p><?php
    $own=$u&&$u['id']===$l['seller_id'];$can=$l['status']==='published'&&$l['stock_qty']>0&&!$l['sold_at'];
    if($l['section']==='subasta'){
        $a=one('SELECT * FROM auctions WHERE listing_id=?',[$l['id']]);$high=one('SELECT b.*,u.display_name FROM bids b JOIN users u ON u.id=b.bidder_id WHERE auction_id=? ORDER BY amount_centavos DESC,b.id LIMIT 1',[$a['id']]);$min=$high?$high['amount_centavos']+$a['min_increment_centavos']:$l['unit_price_centavos']; echo '<span data-auction="'.(int)$a['id'].'" hidden></span>';
        echo '<div class="price-block"><span>'.($high?'Current bid':'Opening bid').'</span><strong data-current-bid>'.money((int)($high['amount_centavos']??$l['unit_price_centavos'])).'</strong><small>'.($high?e($high['display_name']).' is leading':'Be the first to bid').'</small></div><div class="auction-timer">'.icon('clock').'<span data-end="'.e($a['ends_at']).'">'.e($a['status']).'</span><small>Ends '.date('M j, g:i A',strtotime($a['ends_at'])).' PHT</small></div>';
        if($can&&!$own&&$a['status']==='live'){form('bid',['id'=>$a['id'],'request_token'=>bin2hex(random_bytes(18))]);echo '<label>Your bid (PHP)<input name="amount" type="number" min="'.($min/100).'" step="0.01" value="'.($min/100).'" required></label><button class="btn full">Place bid '.icon('gavel').'</button><p class="form-hint">Minimum next bid '.money((int)$min).'. Highest bid wins at the deadline.</p></form>';}
        echo '<details open class="details-box"><summary>Bid history</summary>';foreach(all('SELECT b.*,u.display_name FROM bids b JOIN users u ON u.id=b.bidder_id WHERE auction_id=? ORDER BY amount_centavos DESC,b.id LIMIT 10',[$a['id']]) as $b)echo '<div class="simple-row"><span>'.e($b['display_name']).'</span><strong>'.money((int)$b['amount_centavos']).'</strong></div>';echo '</details>';
    }elseif($l['section']==='arkilikha'){
        echo '<div class="price-block"><span>Make it for a day. Or a little longer.</span><strong>'.money((int)$l['unit_price_centavos']).'<small> / day</small></strong></div><p>'.e($l['condition_notes']).'</p>';
        if($can&&!$own){form('rental_request',['id'=>$l['id']]);echo '<div class="form-row"><label>Pickup date<input type="date" name="start_date" min="'.date('Y-m-d').'" required></label><label>Return date<input type="date" name="end_date" min="'.date('Y-m-d',strtotime('+1 day')).'" required></label></div><div class="quote-preview" data-daily="'.$l['unit_price_centavos'].'" data-rates="'.e(json_encode(all('SELECT min_days,max_days,commission_bps FROM rental_rate_tiers WHERE is_active=1'))).'">Choose your dates to see the rental total.</div><button class="btn full">Request rental '.icon('arrow').'</button><p class="form-hint">Provider approval first, then fake checkout. Rental commission is deducted from the provider’s proceeds.</p></form>';}
        echo '<details class="details-box" open><summary>Reserved dates</summary>';foreach(all("SELECT start_date,end_date FROM rental_bookings WHERE listing_id=? AND (status IN ('confirmed','collected') OR (status='approved' AND hold_expires_at>?))",[$l['id'],now()]) as $r)echo '<p>'.e($r['start_date']).' → '.e($r['end_date']).'</p>';echo '<small>Return date is excluded. Adjacent bookings are allowed.</small></details>';
    }elseif($l['section']==='gawang_hiling'){
        $o=one('SELECT * FROM commission_offers WHERE listing_id=?',[$l['id']]);$s=slots((int)$l['id']);echo '<div class="price-block"><span>Commissions starting at</span><strong>'.money((int)$l['unit_price_centavos']).'</strong><small>'.$s.' open slots · about '.$o['estimated_days'].' days · '.$o['revision_limit'].' revisions</small></div><p>'.e($o['terms']).'</p>';
        if($can&&!$own&&$s>0){?><form method="post" action="/" enctype="multipart/form-data"><?=token_field()?><input type="hidden" name="action" value="commission_request"><input type="hidden" name="id" value="<?=$l['id']?>"><input type="hidden" name="return" value="<?=e($_SERVER['REQUEST_URI'])?>"><label>Tell the artist your idea<textarea name="brief" required maxlength="4000" placeholder="A portrait, a favorite place, a story…"></textarea></label><div class="form-row"><label>Budget (PHP, optional)<input name="budget" type="number" min="1" step="0.01"></label><label>Preferred date (optional)<input name="due_date" type="date" min="<?=date('Y-m-d')?>"></label></div><label>Reference image (optional)<input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="btn full">Request artwork <?=icon('arrow')?></button><p class="form-hint">Your artist will send a quote before any demo payment.</p></form><?php }
    }else{
        echo '<div class="price-block"><span>'.($l['stock_qty']>0?'A piece to make your own':'This one found a home').'</span><strong>'.money((int)$l['unit_price_centavos']).'</strong></div>';
        if($can&&!$own){form('cart_add',['id'=>$l['id']]);if($l['stock_qty']>1)echo '<label>Quantity<input type="number" min="1" max="'.$l['stock_qty'].'" value="1" name="quantity"></label>';echo '<button class="btn full">Add to cart '.icon('bag').'</button></form><p class="form-hint">'.($l['artwork_id']?'One original. One new home.':'Available stock: '.$l['stock_qty']).' · Simulated pickup</p>';}
    }
    if($own)echo '<p class="notice">This is your listing. Manage it in My studio.</p>';
    if(!$can)echo '<p class="notice">This listing is currently unavailable for new transactions.</p>';
    echo '<div class="detail-secondary">';action_button('save',['id'=>$l['id'],'type'=>'listing'],icon('heart').' Save to collection','btn btn-outline full');echo '</div><details class="report-box"><summary>Report this listing</summary>';form('report',['id'=>$l['id'],'type'=>'listing']);echo '<label>Reason<textarea name="reason" maxlength="1000" required></textarea></label><button class="btn btn-small btn-outline">Send report</button></form></details></div></div>';
}
function artists():void{
    page_heading('MUSEO','Every artist has a world to share.','Meet the people behind the pieces. Find a style, a story, or a new favorite.');$q=trim((string)($_GET['q']??''));$badge=(string)($_GET['badge']??'');
    ?><form class="filterbar" method="get"><input type="hidden" name="p" value="artists"><label class="filter-search"><?=icon('search')?><input name="q" aria-label="Search artists" placeholder="Name, region, or specialty" value="<?=e($q)?>"></label><label><span>Artist badge</span><select name="badge"><option value="">All artists</option><option value="sibol" <?=$badge==='sibol'?'selected':''?>>Sibol</option><option value="dalubhasa" <?=$badge==='dalubhasa'?'selected':''?>>Dalubhasa</option></select></label><button class="btn btn-small">Find artists</button></form><div class="artist-grid"><?php
    $sql="SELECT u.*,a.badge,a.specialties FROM users u JOIN artist_profiles a ON a.user_id=u.id WHERE u.status='active' AND (u.display_name LIKE ? OR u.region LIKE ? OR a.specialties LIKE ?)";$args=array_fill(0,3,'%'.$q.'%');if(in_array($badge,['sibol','dalubhasa'])){$sql.=' AND a.badge=?';$args[]=$badge;}$rows=all($sql,$args);if(!$rows)empty_state('No artists found.','Try another name or region.','artists');
    foreach($rows as $i=>$a){echo '<article class="artist-card"><a class="artist-cover" href="'.url('artist',['id'=>$a['id']]).'">';visual_media(one('SELECT m.* FROM media m JOIN artwork_images i ON i.media_id=m.id JOIN artworks w ON w.id=i.artwork_id WHERE w.artist_id=? AND w.status=\'visible\' LIMIT 1',[$a['id']]));echo '</a><div class="artist-card-body">'.avatar($a['display_name'],'large').badge($a['badge']).'<h2><a href="'.url('artist',['id'=>$a['id']]).'">'.e($a['display_name']).'</a></h2><p>'.e($a['specialties']).'</p><span>'.e($a['region']).'</span></div></article>';}
    echo '</div>';
}
function artist_page():void{
    $id=(int)($_GET['id']??0);$a=one("SELECT u.*,a.badge,a.specialties FROM users u JOIN artist_profiles a ON a.user_id=u.id WHERE u.id=? AND u.status='active'",[$id]);if(!$a){empty_state('Artist unavailable.','Browse the artist directory.','artists');return;}
    echo '<div class="artist-profile">'.avatar($a['display_name'],'profile-avatar').'<div><span class="eyebrow">MUSEO / '.e($a['region']).'</span><h1>'.e($a['display_name']).'</h1>'.badge($a['badge']).'<p>'.e($a['specialties']).'</p><p>'.e($a['bio']).'</p></div>';action_button('save',['id'=>$id,'type'=>'artist'],icon('bookmark').' Save artist','btn btn-outline');echo '</div><div class="section-heading"><h2>Inside the portfolio</h2><span>Works, stories, and little worlds</span></div><div class="art-grid">';
    $works=all("SELECT * FROM artworks WHERE artist_id=? AND status='visible' ORDER BY id",[$id]);foreach($works as $w){$l=one("SELECT l.*,u.display_name FROM listings l JOIN users u ON u.id=l.seller_id WHERE artwork_id=? AND l.status IN ('published','sold_out') ORDER BY l.id DESC LIMIT 1",[$w['id']]);if($l)card($l);else{echo '<article class="art-card"><a href="'.url('artwork',['id'=>$w['id']]).'">';visual_media(one('SELECT m.* FROM media m JOIN artwork_images i ON i.media_id=m.id WHERE i.artwork_id=? LIMIT 1',[$w['id']]));echo '</a><div class="card-content"><h3>'.e($w['title']).'</h3><p>'.e($w['medium']).'</p><span class="status">Portfolio work</span></div></article>';}}
    echo '</div><div class="section-heading"><h2>More from this studio</h2></div><div class="art-grid">';foreach(all("SELECT l.*,u.display_name FROM listings l JOIN users u ON u.id=l.seller_id WHERE seller_id=? AND artwork_id IS NULL AND l.status='published'",[$id]) as $l)card($l);echo '</div>';
}
function artwork():void{$w=one("SELECT * FROM artworks WHERE id=? AND status='visible'",[(int)($_GET['id']??0)]);if(!$w)throw new DomainException('Artwork unavailable.');$l=one("SELECT id FROM listings WHERE artwork_id=? AND status IN ('published','sold_out') ORDER BY id DESC LIMIT 1",[$w['id']]);if($l)go('detail',['id'=>$l['id']]);page_heading('MUSEO',$w['title'],$w['medium']);echo '<div class="detail-grid"><div>';visual_media(one('SELECT m.* FROM media m JOIN artwork_images i ON i.media_id=m.id WHERE artwork_id=? LIMIT 1',[$w['id']]));echo '</div><div><p>'.e($w['description']).'</p><p>Portfolio work · Not for sale</p><a class="btn btn-outline" href="'.url('artist',['id'=>$w['artist_id']]).'">Visit artist</a>';action_button('save',['id'=>$w['id'],'type'=>'artwork'],'Save artwork');echo '</div></div>';}
